// Hermetic WASM fixtures generated by testdata/gen (see that program for the
// exact byte layout). They implement the guest ABI documented in host.go.
//
//go:embed testdata/echo.wasm
var echoWasm []byte

//go:embed testdata/hang.wasm
var hangWasm []byte

//go:embed testdata/spin.wasm
var spinWasm []byte

//go:embed testdata/grow.wasm
var growWasm []byte

//go:embed testdata/slow.wasm
var slowWasm []byte

const (
	testService = "test.service"
	testMethod  = "call"
)

// recordingSink captures structured telemetry for assertions; it is safe for
// concurrent use.
type recordingSink struct {
	mu     sync.Mutex
	events []plugin.Event
}

func (s *recordingSink) RecordPluginEvent(_ context.Context, ev plugin.Event) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	cp := make(map[string]any, len(ev.Detail))
	for k, v := range ev.Detail {
		cp[k] = v
	}
	ev.Detail = cp
	s.events = append(s.events, ev)
	return nil
}

func (s *recordingSink) first(kind plugin.EventKind) (plugin.Event, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, e := range s.events {
		if e.Kind == kind {
			return e, true
		}
	}
	return plugin.Event{}, false
}

func (s *recordingSink) hasReason(reason string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, e := range s.events {
		if r, _ := e.Detail["reason"].(string); r == reason {
			return true
		}
	}
	return false
}

func (s *recordingSink) hasCode(code plugin.CallErrorCode) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, e := range s.events {
		if e.Code == string(code) {
			return true
		}
		if c, _ := e.Detail["code"].(string); c == string(code) {
			return true
		}
	}
	return false
}

func (s *recordingSink) snapshot() []plugin.Event { //nolint:unused // debugging aid
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]plugin.Event(nil), s.events...)
}

func newHost(t *testing.T, binary []byte, cfg Config) *Host {
	t.Helper()
	cfg.ModuleBinary = binary
	if cfg.PluginID == "" {
		cfg.PluginID = "wasm-test"
	}
	h, err := New(cfg)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	return h
}

// startHost starts a host and registers a best-effort Stop cleanup.
func startHost(t *testing.T, binary []byte, cfg Config) *Host {
	t.Helper()
	h := newHost(t, binary, cfg)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := h.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() {
		sctx, c := context.WithTimeout(context.Background(), 5*time.Second)
		defer c()
		_ = h.Stop(sctx)
	})
	return h
}

// assertTerminal fails unless the host has reached terminal state with an error.
func assertTerminal(t *testing.T, h *Host) {
	t.Helper()
	select {
	case <-h.Exited():
	case <-time.After(2 * time.Second):
		t.Fatal("host did not reach terminal state")
	}
	if h.ExitError() == nil {
		t.Fatal("expected non-nil ExitError after forced termination")
	}
}

func assertNotActive(t *testing.T, err error) {
	t.Helper()
	var ce *plugin.CallError
	if !errors.As(err, &ce) || ce.Code() != plugin.CodeNotActive {
		t.Fatalf("want NOT_ACTIVE CallError, got %v", err)
	}
}

func TestStartTimeoutBoundsCompilationInstantiationAndHealth(t *testing.T) {
	h := newHost(t, hangWasm, Config{StartTimeout: 100 * time.Millisecond})

	start := time.Now()
	err := h.Start(context.Background())
	elapsed := time.Since(start)

	if err == nil {
		t.Fatal("expected Start to fail for a guest that never answers health")
	}
	if elapsed > time.Second {
		t.Fatalf("Start took %v; compilation+instantiation+health must be bounded by StartTimeout", elapsed)
	}
	assertTerminal(t, h)
}

func TestInvokeCancellationTerminatesCPUboundGuest(t *testing.T) {
	h := startHost(t, spinWasm, Config{
		StartTimeout:  5 * time.Second,
		InvokeTimeout: 30 * time.Second,
	})

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go func() {
		time.Sleep(30 * time.Millisecond)
		cancel()
	}()

	start := time.Now()
	_, err := h.Invoke(ctx, testService, testMethod, nil)
	if err == nil {
		t.Fatal("expected an error when the caller cancels a CPU-bound guest")
	}
	var ce *plugin.CallError
	if !errors.As(err, &ce) || ce.Code() != CodeCanceled {
		t.Fatalf("want CANCELED CallError (typed cancellation), got %v", err)
	}
	if elapsed := time.Since(start); elapsed > 2*time.Second {
		t.Fatalf("cancellation took %v; the guest must be terminated promptly", elapsed)
	}
	assertTerminal(t, h)
}

func TestInvokeTimeoutTerminatesGuest(t *testing.T) {
	h := startHost(t, spinWasm, Config{
		StartTimeout:  5 * time.Second,
		InvokeTimeout: 100 * time.Millisecond,
	})

	start := time.Now()
	_, err := h.Invoke(context.Background(), testService, testMethod, nil)
	if err == nil {
		t.Fatal("expected a timeout error")
	}
	var ce *plugin.CallError
	if !errors.As(err, &ce) || ce.Code() != plugin.CodeTimeout {
		t.Fatalf("want TIMEOUT CallError, got %v", err)
	}
	if elapsed := time.Since(start); elapsed > 2*time.Second {
		t.Fatalf("timeout took %v; the guest must be terminated and the call returned", elapsed)
	}
	assertTerminal(t, h)
}

func TestMemoryGrowthBeyondLimitFailsClosed(t *testing.T) {
	h := startHost(t, growWasm, Config{
		StartTimeout:   5 * time.Second,
		InvokeTimeout:  5 * time.Second,
		MaxMemoryPages: 2,
	})

	_, err := h.Invoke(context.Background(), testService, testMethod, nil)
	if err == nil {
		t.Fatal("expected fail-closed error when the guest grows beyond the memory limit")
	}
	assertTerminal(t, h)
}

func TestConcurrentInvocationsRespectLimit(t *testing.T) {
	h := startHost(t, slowWasm, Config{
		StartTimeout:   5 * time.Second,
		InvokeTimeout:  30 * time.Second,
		MaxConcurrency: 1,
	})

	const n = 8
	var wg sync.WaitGroup
	start := make(chan struct{})
	errs := make([]error, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(i int) {
			defer wg.Done()
			<-start
			_, errs[i] = h.Invoke(context.Background(), testService, testMethod, nil)
		}(i)
	}
	close(start)
	wg.Wait()

	for i, err := range errs {
		if err != nil {
			t.Fatalf("invoke %d failed: %v", i, err)
		}
	}
	if got := h.peakInflight.Load(); got > 1 {
		t.Fatalf("observed %d simultaneous invocations; configured limit is 1", got)
	}
}

func TestCanceledHostRejectsSubsequentInvocations(t *testing.T) {
	h := startHost(t, spinWasm, Config{
		StartTimeout:  5 * time.Second,
		InvokeTimeout: 30 * time.Second,
	})

	ctx, cancel := context.WithCancel(context.Background())
	go func() {
		time.Sleep(30 * time.Millisecond)
		cancel()
	}()
	if _, err := h.Invoke(ctx, testService, testMethod, nil); err == nil {
		t.Fatal("expected the first invocation to be canceled")
	}

	_, err := h.Invoke(context.Background(), testService, testMethod, nil)
	assertNotActive(t, err)
}

func TestStopReturnsWhenShutdownCompletesBeforeGraceDeadline(t *testing.T) {
	const grace = 5 * time.Second
	h := startHost(t, echoWasm, Config{
		StartTimeout:  5 * time.Second,
		InvokeTimeout: 5 * time.Second,
		GracePeriod:   grace,
	})

	start := time.Now()
	if err := h.Stop(context.Background()); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	if elapsed := time.Since(start); elapsed > 2*time.Second {
		t.Fatalf("Stop waited %v despite a cooperative shutdown; grace was %v", elapsed, grace)
	}
}

// TestStopIsGraceBoundedWhileGuestBusy asserts Stop is bounded by GracePeriod
// even when a CPU-bound guest holds the writer. Mutation check: removing the
// host cancel / ctx-aware write lock makes this exceed InvokeTimeout.
func TestStopIsGraceBoundedWhileGuestBusy(t *testing.T) {
	const grace = 200 * time.Millisecond
	h := startHost(t, spinWasm, Config{
		StartTimeout:  5 * time.Second,
		InvokeTimeout: 30 * time.Second,
		GracePeriod:   grace,
	})

	invokeDone := make(chan struct{})
	go func() {
		defer close(invokeDone)
		_, _ = h.Invoke(context.Background(), testService, testMethod, nil)
	}()

	// Wait until the guest call is actually executing and holding the writer.
	waitFor(t, func() bool { return len(h.writeCh) == 1 })

	start := time.Now()
	if err := h.Stop(context.Background()); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	elapsed := time.Since(start)
	<-invokeDone

	if elapsed > 2*time.Second {
		t.Fatalf("Stop took %v while a CPU-bound guest was running; GracePeriod was %v", elapsed, grace)
	}
}

func waitFor(t *testing.T, ok func() bool) {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if ok() {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatal("condition was not met before the deadline")
}

func TestExitedRemainsClosedAndObservable(t *testing.T) {
	h := startHost(t, echoWasm, Config{StartTimeout: 5 * time.Second})
	if err := h.Stop(context.Background()); err != nil {
		t.Fatalf("Stop: %v", err)
	}

	ch1 := h.Exited()
	ch2 := h.Exited()
	if ch1 == nil {
		t.Fatal("Exited returned nil after termination")
	}
	if ch1 != ch2 {
		t.Fatal("Exited must return a stable channel across calls")
	}
	select {
	case <-ch1:
	default:
		t.Fatal("Exited channel must be closed after termination")
	}

	_, err := h.Invoke(context.Background(), testService, testMethod, nil)
	assertNotActive(t, err)
}

// failingSink always rejects an event, for surfacing tests.
type failingSink struct{ err error }

func (s failingSink) RecordPluginEvent(context.Context, plugin.Event) error { return s.err }

// TestProductionHostRejectsNilEvidenceSink proves the wasm production host
// refuses to be constructed without an evidence sink.
func TestProductionHostRejectsNilEvidenceSink(t *testing.T) {
	if _, err := New(Config{PluginID: "wasm-prod", ModuleBinary: echoWasm, RequireEvidence: true}); err == nil {
		t.Fatal("production wasm host accepted a nil evidence sink")
	}
}

// TestMemoryLimitEmitsResourceLimitEvent proves the memory-bound path emits the
// distinct EventResourceLimit kind, carrying the enforced limit, rather than
// only folding into a generic termination.
func TestMemoryLimitEmitsResourceLimitEvent(t *testing.T) {
	sink := &recordingSink{}
	h := startHost(t, growWasm, Config{
		Sink:           sink,
		StartTimeout:   5 * time.Second,
		InvokeTimeout:  5 * time.Second,
		MaxMemoryPages: 2,
	})
	if _, err := h.Invoke(context.Background(), testService, testMethod, nil); err == nil {
		t.Fatal("expected memory limit failure")
	}
	ev, ok := sink.first(plugin.EventResourceLimit)
	if !ok {
		t.Fatalf("no resource-limit event emitted; events=%v", sink.snapshot())
	}
	if ev.Limits.MemoryMB <= 0 {
		t.Fatalf("resource-limit event missing enforced limits: %+v", ev.Limits)
	}
	if r, _ := ev.Detail["reason"].(string); r != "guest_trap" {
		t.Fatalf("resource-limit reason = %v, want guest_trap preserved", ev.Detail["reason"])
	}
}

// TestDroppedTerminalEvidenceIsSurfaced proves a rejected terminal event is
// reported through OnEvidenceError rather than silently swallowed.
func TestDroppedTerminalEvidenceIsSurfaced(t *testing.T) {
	sentinel := errors.New("injected sink rejection")
	var mu sync.Mutex
	var surfaced []error
	h := newHost(t, echoWasm, Config{
		Sink:            failingSink{err: sentinel},
		StartTimeout:    5 * time.Second,
		OnEvidenceError: func(err error) { mu.Lock(); surfaced = append(surfaced, err); mu.Unlock() },
	})
	if err := h.Start(context.Background()); err != nil {
		t.Fatalf("Start: %v", err)
	}
	// Ignore events from Start; assert the terminal (Stop) fact is surfaced.
	mu.Lock()
	surfaced = nil
	mu.Unlock()
	if err := h.Stop(context.Background()); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	mu.Lock()
	n := len(surfaced)
	var first error
	if n > 0 {
		first = surfaced[0]
	}
	mu.Unlock()
	if n == 0 {
		t.Fatal("dropped terminal evidence was swallowed")
	}
	if !errors.Is(first, sentinel) {
		t.Fatalf("surfaced error = %v, want %v", first, sentinel)
	}
}

func TestEveryLimitOrCancellationEmitsEvidence(t *testing.T) {
	t.Run("invoke_timeout", func(t *testing.T) {
		sink := &recordingSink{}
		h := startHost(t, spinWasm, Config{
			Sink:          sink,
			StartTimeout:  5 * time.Second,
			InvokeTimeout: 80 * time.Millisecond,
		})
		if _, err := h.Invoke(context.Background(), testService, testMethod, nil); err == nil {
			t.Fatal("expected timeout")
		}
		if !sink.hasReason("invoke_timeout") && !sink.hasCode(plugin.CodeTimeout) {
			t.Fatalf("no timeout evidence emitted: %+v", sink.snapshot())
		}
	})

	t.Run("invoke_canceled", func(t *testing.T) {
		sink := &recordingSink{}
		h := startHost(t, spinWasm, Config{
			Sink:          sink,
			StartTimeout:  5 * time.Second,
			InvokeTimeout: 30 * time.Second,
		})
		ctx, cancel := context.WithCancel(context.Background())
		go func() {
			time.Sleep(30 * time.Millisecond)
			cancel()
		}()
		if _, err := h.Invoke(ctx, testService, testMethod, nil); err == nil {
			t.Fatal("expected cancellation")
		}
		if !sink.hasReason("invoke_canceled") {
			t.Fatalf("no cancellation evidence emitted: %+v", sink.snapshot())
		}
	})

	t.Run("memory_limit", func(t *testing.T) {
		sink := &recordingSink{}
		h := startHost(t, growWasm, Config{
			Sink:           sink,
			StartTimeout:   5 * time.Second,
			InvokeTimeout:  5 * time.Second,
			MaxMemoryPages: 2,
		})
		if _, err := h.Invoke(context.Background(), testService, testMethod, nil); err == nil {
			t.Fatal("expected memory limit failure")
		}
		if !sink.hasReason("guest_trap") {
			t.Fatalf("no memory-limit/trap evidence emitted: %+v", sink.snapshot())
		}
	})

	t.Run("start_timeout", func(t *testing.T) {
		sink := &recordingSink{}
		h := newHost(t, hangWasm, Config{
			Sink:         sink,
			StartTimeout: 80 * time.Millisecond,
		})
		if err := h.Start(context.Background()); err == nil {
			t.Fatal("expected start timeout")
		}
		if !sink.hasReason("start_timeout") {
			t.Fatalf("no start-timeout evidence emitted: %+v", sink.snapshot())
		}
	})
}

// TestHostHealthyReflectsLifecycle pins the real-host health signal the
// production assembly gates activation on: an unstarted host is unhealthy, a
// running host answers Healthy, and a stopped host is unhealthy again. Deleting
// Host.Healthy breaks the assembly's mandatory InstanceHost contract.
func TestHostHealthyReflectsLifecycle(t *testing.T) {
	h := newHost(t, echoWasm, Config{})
	if err := h.Healthy(context.Background()); err == nil {
		t.Fatal("an unstarted host must be unhealthy")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := h.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	if err := h.Healthy(context.Background()); err != nil {
		t.Fatalf("a running host must be healthy: %v", err)
	}
	sctx, scancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer scancel()
	if err := h.Stop(sctx); err != nil {
		t.Fatalf("Stop: %v", err)
	}
	if err := h.Healthy(context.Background()); err == nil {
		t.Fatal("a stopped host must be unhealthy")
	}
}
